// PyMentor Lab v1.1 — distribution assembler.
//
// Run from the repository root:
//     node dist/build-dist.mjs
//
// What this script does:
//   1. mkdir -p dist/backend-deploy/code
//            dist/installer-source/installer-assets
//            dist/installer
//   2. Copy the source tree into dist/backend-deploy/code/ (skipping
//      node_modules, .venv, .git, dist, build artifacts, caches, raw inputs).
//   3. Write a ZIP of the entire dist/backend-deploy/ folder to
//      dist/backend-deploy/pymentor-backend-v1.1.zip using a self-contained
//      Node-only ZIP writer (no external deps, no shell-out).
//   4. Copy that zip to dist/installer-source/installer-assets/backend-deploy.zip
//      so the Inno Setup stage can embed it.
//   5. Print a summary: file count, zip path, zip size.
//
// The committed source under dist/backend-deploy/ (docker-compose.yml,
// .env.example, *.sh, *.ps1, README.md) is NOT regenerated by this script —
// only code/ and the zip are.

import { createWriteStream, existsSync, mkdirSync, readdirSync, rmSync, statSync } from 'node:fs';
import { copyFile, cp, readFile } from 'node:fs/promises';
import { join, relative, resolve, sep } from 'node:path';
import { deflateRawSync, constants as zlibConstants } from 'node:zlib';
import { fileURLToPath } from 'node:url';
import process from 'node:process';

const __filename = fileURLToPath(import.meta.url);
const __dirname = resolve(__filename, '..');
const repoRoot = resolve(__dirname, '..');

const DIST_DIR = join(repoRoot, 'dist');
const BACKEND_DEPLOY_DIR = join(DIST_DIR, 'backend-deploy');
const CODE_DIR = join(BACKEND_DEPLOY_DIR, 'code');
const INSTALLER_SOURCE_DIR = join(DIST_DIR, 'installer-source');
const INSTALLER_ASSETS_DIR = join(INSTALLER_SOURCE_DIR, 'installer-assets');
const INSTALLER_DIR = join(DIST_DIR, 'installer');

const VERSION = 'v1.1';
const ZIP_NAME = `pymentor-backend-${VERSION}.zip`;
const ZIP_PATH = join(BACKEND_DEPLOY_DIR, ZIP_NAME);
const INSTALLER_ASSET_ZIP = join(INSTALLER_ASSETS_DIR, 'backend-deploy.zip');

// Source directories/files copied into code/. Directories are recursive.
const SOURCE_DIRS = ['backend', 'workers', 'packages', 'knowledge', 'infra', 'sandbox'];
const SOURCE_FILES = [
    'pyproject.toml',
    'pnpm-workspace.yaml',
    'pnpm-lock.yaml',
    'tsconfig.base.json',
    'package.json',
    'README.md',
    'uv.lock',
    '.dockerignore',
    '.gitattributes',
    '.editorconfig',
    '.prettierrc',
    '.prettierignore',
    '.nvmrc',
    '.python-version',
];

// Paths to skip while walking the source tree. Matched against absolute path
// segments so they apply at any depth.
const SKIP_SEGMENTS = new Set([
    'node_modules',
    '.venv',
    'venv',
    '.git',
    '.github',
    '.making',
    '.worktrees',
    '.zcode',
    '.pnpm-store',
    '__pycache__',
    '.pytest_cache',
    '.mypy_cache',
    '.ruff_cache',
    '.tsbuildinfo',
    'dist',
    'build',
    'out',
    'coverage',
    '.nyc_output',
    '.eslintcache',
    'raw',
    '.idea',
    '.vscode',
]);

// Skip files whose basename matches these.
const SKIP_FILE_RE = /\.(pyc|pyo|swp|log)$/i;

// Skip a path based ONLY on the segments below its source root. We must not
// inspect the absolute path itself, because the repo might live under a path
// that legitimately contains one of these names (e.g. a worktree under
// `.worktrees/`, or this script's own `dist/` parent).
function shouldSkipRel(relativePath) {
    const parts = relativePath.split(sep);
    for (const seg of parts) {
        if (SKIP_SEGMENTS.has(seg)) return true;
    }
    const base = parts[parts.length - 1];
    if (SKIP_FILE_RE.test(base)) return true;
    if (base === '.DS_Store' || base === 'Thumbs.db') return true;
    return false;
}

function log(msg) {
    process.stdout.write(`[build-dist] ${msg}\n`);
}

function ensureDir(p) {
    mkdirSync(p, { recursive: true });
}

// Build a cp() filter that skips paths relative to a specific source root.
// cp() invokes the filter with the absolute SOURCE path of each entry; we
// convert it back to a path relative to srcRoot before applying skip rules.
function makeCopyFilter(srcRoot) {
    return (src) => {
        const rel = relative(srcRoot, src);
        return !shouldSkipRel(rel);
    };
}

async function copySource() {
    // Wipe a stale code/ tree so removed files do not leak into the zip.
    if (existsSync(CODE_DIR)) {
        rmSync(CODE_DIR, { recursive: true, force: true });
    }
    ensureDir(CODE_DIR);

    let dirCount = 0;
    let fileCount = 0;
    let totalBytes = 0;
    const seen = [];

    for (const dir of SOURCE_DIRS) {
        const src = join(repoRoot, dir);
        if (!existsSync(src)) {
            log(`skip (missing): ${dir}`);
            continue;
        }
        const dst = join(CODE_DIR, dir);
        // The filter is anchored at `src` so it never inspects path segments
        // above the source root (e.g. worktree dir names, this dist/ parent).
        await cp(src, dst, { recursive: true, filter: makeCopyFilter(src) });
        dirCount++;
        seen.push(dir);
    }

    for (const file of SOURCE_FILES) {
        const src = join(repoRoot, file);
        if (!existsSync(src)) {
            log(`skip (missing): ${file}`);
            continue;
        }
        const dst = join(CODE_DIR, file);
        // cp on a single file uses its file copy path.
        await cp(src, dst, { recursive: false });
        seen.push(file);
    }

    // Count files + bytes for the summary.
    const walk = (dir) => {
        const entries = readdirSync(dir, { withFileTypes: true });
        for (const e of entries) {
            const full = join(dir, e.name);
            if (e.isDirectory()) walk(full);
            else if (e.isFile()) {
                fileCount++;
                totalBytes += statSync(full).size;
            }
        }
    };
    walk(CODE_DIR);

    log(`copied ${seen.length} top-level entries (${dirCount} dirs) into code/`);
    log(`code/ contains ${fileCount} files, ${(totalBytes / 1024 / 1024).toFixed(2)} MiB uncompressed`);
    return { fileCount, totalBytes };
}

// ---------------------------------------------------------------------------
// Minimal ZIP writer (PKZIP 2.0 / STORE + DEFLATE).
// No external dependencies. Produces archives compatible with 7-Zip, Windows
// Explorer, `unzip`, PowerShell Expand-Archive, and Java's ZipInputStream.
// ---------------------------------------------------------------------------

const crcTable = (() => {
    const table = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
        let c = n;
        for (let k = 0; k < 8; k++) {
            c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
        }
        table[n] = c >>> 0;
    }
    return table;
})();

function crc32(buf) {
    let c = 0xFFFFFFFF;
    for (let i = 0; i < buf.length; i++) {
        c = crcTable[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
    }
    return (c ^ 0xFFFFFFFF) >>> 0;
}

function u16(n) {
    const b = Buffer.alloc(2);
    b.writeUInt16LE(n & 0xFFFF, 0);
    return b;
}
function u32(n) {
    const b = Buffer.alloc(4);
    b.writeUInt32LE(n >>> 0, 0);
    return b;
}

// DOS date/time encoding (always uses local time). The exact time does not
// matter for correctness; we use the file's mtime so re-builds are stable.
function dosDateTime(unixMs) {
    const d = new Date(unixMs);
    // Clamp to DOS-valid range (1980-2107).
    const year = Math.max(1980, Math.min(2107, d.getFullYear()));
    const month = Math.max(1, Math.min(12, d.getMonth() + 1));
    const day = Math.max(1, Math.min(31, d.getDate()));
    const hour = Math.max(0, Math.min(23, d.getHours()));
    const minute = Math.max(0, Math.min(59, d.getMinutes()));
    const second = Math.min(30, Math.floor(d.getSeconds() / 2)); // 2s granularity
    const dosDate = ((year - 1980) << 9) | (month << 5) | day;
    const dosTime = (hour << 11) | (minute << 5) | second;
    return { date: dosDate, time: dosTime };
}

async function main() {
    log(`repo root: ${repoRoot}`);
    log(`version: ${VERSION}`);

    ensureDir(BACKEND_DEPLOY_DIR);
    ensureDir(CODE_DIR);
    ensureDir(INSTALLER_SOURCE_DIR);
    ensureDir(INSTALLER_ASSETS_DIR);
    ensureDir(INSTALLER_DIR);

    // 1. Copy source tree.
    const { fileCount, totalBytes } = await copySource();

    // 2. Sanity check that the deploy scripts + compose file exist alongside.
    const required = [
        'docker-compose.yml',
        '.env.example',
        'README.md',
        'deploy.sh', 'deploy.ps1',
        'upgrade.sh', 'upgrade.ps1',
        'rollback.sh', 'rollback.ps1',
        'backup.sh', 'backup.ps1',
        'restore.sh', 'restore.ps1',
        'healthcheck.sh', 'healthcheck.ps1',
    ];
    for (const r of required) {
        if (!existsSync(join(BACKEND_DEPLOY_DIR, r))) {
            log(`WARN: expected source file is missing in backend-deploy/: ${r}`);
        }
    }

    // 3. Remove any stale zip.
    for (const p of [ZIP_PATH, INSTALLER_ASSET_ZIP]) {
        if (existsSync(p)) rmSync(p, { force: true });
    }

    // 4. Zip the entire backend-deploy/ folder, preserving a top-level
    //    backend-deploy/ entry so the archive unpacks to a single dir.
    log(`zipping ${BACKEND_DEPLOY_DIR} -> ${ZIP_PATH} ...`);
    const { entryCount, archiveSize } = await zipSingleDir(BACKEND_DEPLOY_DIR, ZIP_PATH, 'backend-deploy');

    log(`zip written: ${entryCount} entries, ${(archiveSize / 1024 / 1024).toFixed(2)} MiB`);

    // 5. Copy the zip to installer-assets/backend-deploy.zip.
    await copyFile(ZIP_PATH, INSTALLER_ASSET_ZIP);
    log(`copied zip to ${INSTALLER_ASSET_ZIP}`);

    // 6. Print summary.
    const zipStat = statSync(ZIP_PATH);
    console.log('');
    console.log('==============================================================');
    console.log('  build-dist summary');
    console.log('==============================================================');
    console.log(`  source files copied : ${fileCount}`);
    console.log(`  source size (raw)   : ${(totalBytes / 1024 / 1024).toFixed(2)} MiB`);
    console.log(`  zip entries         : ${entryCount}`);
    console.log(`  zip path            : ${relative(repoRoot, ZIP_PATH)}`);
    console.log(`  zip size            : ${(zipStat.size / 1024 / 1024).toFixed(2)} MiB (${zipStat.size} bytes)`);
    console.log(`  installer asset     : ${relative(repoRoot, INSTALLER_ASSET_ZIP)}`);
    console.log('==============================================================');
}

// Helper: zip a single directory, emitting entries with a chosen top-level
// prefix so the archive unpacks to a single dir (backend-deploy/...).
//
// Directory entries are NOT emitted explicitly. Reasons:
//   * Every file entry already names its full path, so unzippers create the
//     intermediate directories automatically.
//   * PowerShell's Expand-Archive (the most common Windows extractor for users
//     without 7-Zip) mishandles explicit directory entries: it tries to
//     New-Item each one and aborts when a directory already exists.
//   * 7-Zip, unzip, WinRAR, Java ZipInputStream, and Python zipfile all
//     accept archives with no directory entries.
// Empty directories are therefore not preserved, which is fine for this
// package (every shipped directory contains files).
async function zipSingleDir(absDir, outPath, topPrefix) {
    const entries = [];
    function walk(d, rel) {
        const items = readdirSync(d, { withFileTypes: true }).slice().sort((a, b) => a.name.localeCompare(b.name));
        for (const it of items) {
            const abs = join(d, it.name);
            const relName = rel ? `${rel}/${it.name}` : it.name;
            if (it.isDirectory()) {
                walk(abs, relName);
            } else if (it.isFile()) {
                entries.push({ kind: 'file', abs, rel: relName });
            }
        }
    }
    walk(absDir, '');

    // Prefix every entry.
    for (const e of entries) e.rel = `${topPrefix}/${e.rel}`;

    const out = createWriteStream(outPath);
    const central = [];
    const writeChunk = (buf) => new Promise((res, rej) => out.write(buf, (err) => err ? rej(err) : res()));
    let offset = 0;
    for (const e of entries) {
        const nameBuf = Buffer.from(e.rel, 'utf8');
        const st = statSync(e.abs);
        const { date, time } = dosDateTime(st.mtimeMs);
        let data;
        let method;
        let compressed;
        data = await readFile(e.abs);
        if (data.length === 0) {
            method = 0; compressed = data;
        } else {
            const deflated = deflateRawSync(data, { level: zlibConstants.Z_BEST_COMPRESSION });
            if (deflated.length < data.length) { method = 8; compressed = deflated; }
            else { method = 0; compressed = data; }
        }
        const crc = crc32(data);
        const localHeader = Buffer.concat([
            u32(0x04034b50), u16(20), u16(0), u16(method),
            u16(time), u16(date), u32(crc),
            u32(compressed.length), u32(data.length),
            u16(nameBuf.length), u16(0), nameBuf,
        ]);
        await writeChunk(localHeader);
        if (compressed.length > 0) await writeChunk(compressed);
        central.push({
            method, crc,
            compressedSize: compressed.length,
            uncompressedSize: data.length,
            nameBuf, time, date,
            localHeaderOffset: offset,
        });
        offset += localHeader.length + compressed.length;
    }
    const cdStart = offset;
    let cdSize = 0;
    for (const c of central) {
        const rec = Buffer.concat([
            u32(0x02014b50), u16(20), u16(20), u16(0), u16(c.method),
            u16(c.time), u16(c.date), u32(c.crc),
            u32(c.compressedSize), u32(c.uncompressedSize),
            u16(c.nameBuf.length), u16(0), u16(0), u16(0), u16(0),
            u32(0), u32(c.localHeaderOffset), c.nameBuf,
        ]);
        cdSize += rec.length;
        await writeChunk(rec);
    }
    offset += cdSize;
    const eocd = Buffer.concat([
        u32(0x06054b50), u16(0), u16(0),
        u16(central.length), u16(central.length),
        u32(cdSize), u32(cdStart), u16(0),
    ]);
    await writeChunk(eocd);
    await new Promise((res, rej) => { out.end(() => res()); out.on('error', rej); });
    return { entryCount: central.length, archiveSize: offset };
}

main().catch((err) => {
    console.error('[build-dist][FATAL]', err);
    process.exit(1);
});
